#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <idn2.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Failed to open %s\n", argv[1]);
        return 1;
    }

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    char *data = malloc(size + 1);
    fread(data, 1, size, f);
    data[size] = 0;
    fclose(f);

    char *out;
    int rc;

    /* Try with various flags */
    int flags[] = {0, IDN2_NFC_INPUT, IDN2_TRANSITIONAL, IDN2_NONTRANSITIONAL,
                   IDN2_TRANSITIONAL|IDN2_USE_STD3_ASCII_RULES,
                   IDN2_NONTRANSITIONAL|IDN2_USE_STD3_ASCII_RULES};

    for (int i = 0; i < sizeof(flags)/sizeof(flags[0]); i++) {
        rc = idn2_to_ascii_8z(data, &out, flags[i]);
        if (rc == IDN2_OK) {
            printf("OK: %s\n", out);
            idn2_free(out);
        }
    }

    free(data);
    return 0;
}
EOF
